"use client";

import * as React from "react";
import { Slider as SliderPrimitive } from "@base-ui/react/slider";

import { cn } from "@/lib/utils";
import { primaryFinish, optionTrack } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Mallow Slider: a lilac groove whose fill and knob carry the solid violet primary finish, one knob per value. */
const Slider = React.forwardRef<HTMLDivElement, WithClassName<SliderPrimitive.Root.Props>>(
  ({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
    const _values = Array.isArray(value) ? value : Array.isArray(defaultValue) ? defaultValue : [min];

    return (
      <SliderPrimitive.Root
        ref={ref}
        data-slot="slider"
        thumbAlignment="edge"
        defaultValue={defaultValue}
        value={value}
        min={min}
        max={max}
        className={cn("relative w-full data-[disabled]:opacity-50", className)}
        {...props}
      >
        <SliderPrimitive.Control className="relative flex h-6 w-full touch-none select-none items-center">
          <SliderPrimitive.Track
            data-slot="slider-track"
            className={cn("relative h-2 w-full grow overflow-hidden rounded-full", optionTrack)}
          >
            <SliderPrimitive.Indicator data-slot="slider-range" className="rounded-full bg-(image:--violet-face)" />
          </SliderPrimitive.Track>
          {Array.from({ length: _values.length }, (_, index) => (
            <SliderPrimitive.Thumb
              key={index}
              data-slot="slider-thumb"
              className={cn(
                "block size-6 cursor-grab rounded-full active:cursor-grabbing",
                primaryFinish,
                "transition-[scale,box-shadow] duration-fast ease-(--ease-out) active:scale-95 motion-reduce:active:scale-100",
                "has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring",
                "data-[disabled]:pointer-events-none",
              )}
            />
          ))}
        </SliderPrimitive.Control>
      </SliderPrimitive.Root>
    );
  },
);
Slider.displayName = "Slider";

export { Slider };
